const data = $json;

function daysSince(isoString) {
  const then = new Date(isoString);
  const now = new Date();
  return Math.floor((now - then) / (1000 * 60 * 60 * 24));
}

let recencyScore;
if (data.release_date) {
  const days = daysSince(data.release_date);
  recencyScore = Math.max(0, 100 - (days / 730 * 100));
} else {
  recencyScore = 0;
}

let activityScore = null;
let activityAvailable = false;
if (data.github_archived) {
  activityScore = 0;
  activityAvailable = true;
} else if (data.github_last_push) {
  const days = daysSince(data.github_last_push);
  activityScore = Math.max(0, 100 - (days / 730 * 100));
  activityAvailable = true;
}

const vulnCount = data.historical_vuln_count || 0;
const securityScore = Math.max(0, 100 - vulnCount * 5);

let composite;
if (activityAvailable) {
  composite = recencyScore * 0.3 + activityScore * 0.3 + securityScore * 0.4;
} else {
  composite = recencyScore * (0.3 / 0.7) + securityScore * (0.4 / 0.7);
}

return {
  json: {
    ...data,
    recency_score: Math.round(recencyScore * 10) / 10,
    activity_score: activityAvailable ? Math.round(activityScore * 10) / 10 : null,
    security_score: Math.round(securityScore * 10) / 10,
    health_score: Math.round(composite * 10) / 10
  }
};
